import json, re, os

ref=json.load(open('test-assignment/reference/questions.json'))['questions']
qdata=ref  # array of 24 arrays of 4 {type,text}

def esc(s): return s.replace('\\','\\\\').replace('"','\\"').replace('>','&gt;')

# Build the JS QUESTIONS block
item_lines=[]
for items in qdata:
    parts=[{"type":"%s"%it['type'],"text":"%s"%esc(it['text'])} it in items]
    item_lines.append("  ["+"},\n    ".join("{\n      "+",\n      ".join(p for p in parts).rstrip()+"}"]")
qblock="var DISC_DATA=["+", ".join(item_lines)+"];\n"

# CSS
CSS=r"""
:root{--bg:#0f1728b3;--card:#fff;--ink:#0e1728;--soft:#4a556880;--line:#e6eaf0;--ac:#6d5efc;--ac2:#38bdf8;--d:#ef4444;--i:#f59e0b;--s:#22c55e;--c:#3b82f6}
*{box-sizing:border-box}
body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;color:var(--ink);background:linear-gradient(145deg,#101828,#1b2540);min-height:100vh;display:flex;flex-direction:column}
.wrap{max-width:980px;width:100%;margin:0 auto;padding:24px 20px 70px}
.hero{text-align:center;color:#fff;padding:34px 20px 8px}
.badge{display:inline-block;padding:7px 14px;border:1px solid rgba(255,255,255,.25);border-radius:999px;font-size:12px;letter-spacing:.02em;color:#cbd5e1;margin-bottom:16px}
.hero h1{font-size:clamp(24px,4.4vw,42px);margin:0 0 12px;font-weight:800;line-height:1.12;letter-spacing:-0.02em}
.hero p{max-width:620px;margin:0 auto 24px;font-size:clamp(14px,2.3vw,17px);color:#cbd5e1;line-height:1.55}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;margin:4px;border:none;cursor:pointer;font-size:15px;font-weight:700;padding:13px 26px;border-radius:12px;background:linear-gradient(90deg,var(--ac),var(--ac2));color:#fff;box-shadow:0 10px 26px rgba(0,0,0,.25);transition:opacity .2s,transform .1s}
.btn:hover{opacity:.95}
.btn:active{transform:translateY(1px)}
.btn--ghost{background:transparent;color:#cbd5e1;border:1px solid rgba(255,255,255,.28);box-shadow:none}
.btn--ghost:hover{background:rgba(255,255,255,.08)}
.overlay{position:fixed;inset:0;background:rgba(9,14,30,.66);display:none;align-items:flex-start;justify-content:center;padding:18px 12px;overflow-y:auto;z-index:80}
.overlay.open{display:flex}
.modal{position:relative;background:var(--card);border-radius:20px;width:100%;max-width:920px;box-shadow:0 24px 60px rgba(0,0,0,.35);margin:6px 0;overflow:hidden}
.modal__head{padding:22px 24px 16px}
.modal__title{margin:0;font-size:21px;font-weight:800}
.modal__sub{color:var(--soft);font-size:13.5px;margin:6px 0 0}
.modal__lead{margin:9px 0 0;font-size:13.5px;font-weight:600}
.__close{position:absolute;top:12px;right:10px;background:transparent;border:none;cursor:pointer;font-size:26px;color:var(--soft);width:34px;height:34px;border-radius:8px}
.__close:hover{background:var(--line);color:var(--ink)}
.tabs{display:flex;flex-wrap:wrap;gap:6px;padding:10px 20px;border-bottom:1px solid var(--line);overflow-x:auto}
.tab{border:1px solid var(--line);background:#fff;color:var(--soft);border-radius:999px;padding:6px 12px;font-size:12.5px;font-weight:700;cursor:pointer;white-space:nowrap}
