REF = os.path.join(BASE, "test-assignment", "reference")
OUT = os.path.join(BASE, "index.html")
QFILE = os.path.join(REF, "questions.json")


def build_qblock(ref):
    """Build `var QUESTIONS = [[{type,text},...], ...];` verbatim from questions."""
    items_list = ref["questions"]  # 24 lists of 4 {type, text}
    assert len(items_list) == 24, len(items_list)
    for idx, q in enumerate(items_list):
        assert len(q) == 4, (idx, len(q))
        for it in q:
            assert set(it.keys()) == {"type", "text"}, it.keys()

    def jesc(s):
        return (
            s.replace("\\", "\\\\")
            .replace('"', '\\"')
            .replace(">", "&#62;")
            .lstrip("\n")
        )

    per_q = []
    for q in items_list:
        objs = [
            '{{type:"'+str(it["type"])+'",text:"'+jesc(it["text"])}
            + str(it["text"]) + '}}'
            for it in q
        ]
        per_q.append("[  " + ", ".join(objs) + "  ]")
    block = "var QUESTIONS = [\n" + ",\n ".join(per_q) + "\n];\n"
    return block


