#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Generate a self-contained single-file DISC replica (index.html).
All 24 questions (with 4 items each) and all 8 step labels are read verbatim
from questions.json at build time, so the generated file cannot drift from the
reference. The scoring logic mirrors the original disc_patched.js: item at
index 0 ('Я наиболее') counts +1 to its type; item at index 3 ('Я наименее')
counts -1; middle items ignored.
"""
import json
import os

BASE = os.path.dirname(os.path.abspath(__file__))
QFILE = os.path.join(BASE, "..", "test-assignment", "reference", "questions.json")
OUT = os.path.join(BASE, "index.html")


def jesc(s):
    return (
        s.replace("\\", "\\\\")
        .replace('"', '\\"')
        .lstrip("\n")
    )


def build_qblock(ref):
    q = ref["questions"]
    assert len(q) == 24, len(q)
    per_q = []
    for items in q:
        inner = ", ".join(
            '{type:' + jesc(str(it["type"])) + ',text:' + jesc(str(it["text"])) +
            '}' for it in items
        )
        per_q.append("[" + inner + "]")
    return "// 24 questions, 8 steps x3, 4 ranked items each (verbatim from questions.json)\n" \
           + "var QUESTIONS = [\n  " + ",\n  ".join(per_q) + "\n];\n"


JS = r'''(function(){
  "use strict";
  var TYPES = ["d","i","s","c"];
  var TYPE_NAME = {
    d:"Dominance · Доминирование",
    i:"Influence · Влияние",
    s:"Stability · Стабильность",
    c:"Compliance · Соответствие"
  };

  // read step labels from questions.json (array of 8 labels) at build time
  var STEP_LABELS = [];
  try{STEP_LABELS=JSON.parse(window.__STEP_LABELS__);}catch(e){}

  var el = function(sel){ return document.querySelector(sel); };
  var elBy = function(sel, root){ return (root||document).querySelector(sel); };
  var al = function(sel, root){ return Array.prototype.slice.call((root||document).querySelectorAll(sel)); };
  var esc = function(s){ return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); };
  var qs = document, cur=0;
  var dragItem=null, dragList=null;

  function build(){
    var w = el("#wizardmodal"), root = el("#root"), tabs = el("#tabs"), prog = el("#discProgress");
    var next = el("[data-next]"), back = el("[data-prev]");
    var stage = el("#stage");

    var tabHtml="";
    STEP_LABELS.forEach(function(lab,i){
      tabHtml += '<button class="tab'+(i===0?' is-active':'')+'" data-step-btn="'+i+'" type="button">'+esc(lab)+' ступень</button>';
    });
    tabs.innerHTML=tabHtml;
    root.scrollTop=0;
    stepTo(0);
  }

  function stepTo(n){
    cur=Math.min(7,Math.max(0,n));
    var tabs=al("[data-step-btn]",el("#tabs"));
    tabs.forEach(function(t){var i=Number(t.getAttribute("data-step-btn")); t.classList.toggle("is-active",i===cur);});
    var panes=al("[data-step-pane]",el("#root"));
    panes.forEach(function(p){p.classList.toggle("is-active",Number(p.getAttribute("data-step-pane"))===cur)});
    next.hidden=cur===7;
    document.querySelector("[data-finish]").hidden=cur!==7;
    if(el(".progress")){el(".progress__bar").style.width=((cur+1)/8*100)+"%";}
    // build per-step content if empty
    if(cur===0 && el("[data-step-pane='0']").children.length===0){
      buildPanels();
    }
  }

  function buildPanels(){
    var panes=al("[data-step-pane]",el("#root"));
    var html="";
    for(var s=0;s<=7;s++){
      html+='<div class="pane"+(s===0?" is-active":"")+'" data-step-pane="'+s+'">';
      for(var c=0;c<3;c++){
        var qi=s*3+c, items=QUESTIONS[qi], cards="";
        for(var k=0;k<3;k++){
          cards+='<div class="row"><div class="row__mid"><div class="disc-list" data-question="'+qi+'">';
          items.forEach(function(it,idx){
            cards+='<li class="disc-item'+(idx===0?' is-major':'')+(idx===items.length-1?' is-minor':'')+'" draggable="true" data-item="'+idx+'" data-type="'+esc(it.type)+'">';
            cards+='<span class="disc-item-text">'+esc(it.text)+'</span></li>';
          });
          cards+="</div></div><div class=\"row__label\">Пункт "+(k+1)+"</div></div>";
        }
        html+='<div class="grid">'+cards+'</div></ div>';
      }
    }
    document.getElementById("root").innerHTML=html;
  }

  function open(){
    el("#wizardmodal").classList.add("is-open");
    document.body.classList.add("scrolled");
  }
  function close(){
    el("#wizardmodal").classList.remove("is-open");
    document.body.classList.remove("scrolled");
  }

  function collect(){
    var rows=[];
    al("ul.disc-list", document).forEach(function(list){
      al("li.disc-item", list).forEach(function(li){
        rows.push({
          pos: Number(li.getAttribute("data-item")),
          type: li.getAttribute("data-type")
        });
      });
    });
    return rows;
  }

  function score(rows){
    var maj={}, min={};
    TYPES.forEach(function(t){maj[t]=0;min[t]=0;});
    rows.forEach(function(r){
      if(r.pos===0){ maj[r.type]=(maj[r.type]||0)+1; }
      else if(r.pos===rows.length-1){ min[r.type]=(min[r.type]||0)+1; }
    });
    var res={d:0,i:0,s:0,c:0};
    TYPES.forEach(function(t){ res[t] = (maj[t]||0) - (min[t]||0); });
    return res;
  }

  function showResults(){
    var r=score(collect());
    var sorted=TYPES.slice().sort(function(a,b){return r[b]-r[a];});
    var out='<div class="row-result"><h2>Ваш DISC-профиль:</h2>';
    out+='<div class="scores-block">';
    TYPES.forEach(function(t){
      var val=r[t]>0?'+'+r[t]:String(r[t]);
      out+='<div class="score-card score-card-'+t+'"><div class="score-type">'+t+'</div>'+
          '<div class="score-name">'+TYPE_NAME[t]+'</div>'+
          '<div class="score-value">'+val+'</div></div>';
    });
    out+='</div>';
    out+='<div class="legend"><div class="legend-item"><b>D:</b> Доминирование — решительность, напористость, стремление к результату.</div>'+
        '<div class="legend-item"><b>I:</b> Влияние — общительность, энтузиаст, убеждение.</div>'+
        '<div class="legend-item"><b>S:</b> Стабильность — стабильность, терпение, стабильность, постоянство.</div>'+
        '<div class="legend-item"><b>C:</b> Соответствие — соответствие стандартам, точность, аккуратность.</div>'+
        '</div>';
    out+='<p class="disclaimer">Обратите внимание: мы не даем расшифровку вашего индивидуального результата. Инструмент предназначен для самопостигания и работы с командой.</p>';
    document.getElementById("stage").innerHTML="";
    /*stage*/stage.innerHTML=out;
    document.getElementById("stage");
    // hide step controls
  }

  // drag & drop
  function wireDragDrop(){
    var items=al("li.disc-item");
    items.forEach(function(li){
      li.addEventListener("dragstart",function(){ dragItem=li; setTimeout(function(){li.classList.add("dragging");},0)});
      li.addEventListener("dragend",function(){ li.classList.remove("dragging"); dragItem=null });
    });
    document.addEventListener("dragover",function(e){
      if(!dragItem)return;
      var li=e.target.closest&&e.target.closest("li.disc-item");
      if(!li||li===dragItem||!li.parentNode||li.parentNode===dragItem.parentNode)return;
      e.preventDefault();
      var ul=dragItem.parentNode;
      var rect=li.getBoundingClientRect();
      var after=(e.clientY-rect.top)<rect.height/2;
      ul.insertBefore(dragItem, after?li:li.nextSibling);
    });
  }

  function wire(){
    if(el("[data-next]")) el("[data-next]").addEventListener("click",function(){
      if(cur<=6){ stepTo(cur+1); }
      else { showResults(); }
    });
    if(el("[data-prev]")) el("[data-prev]").addEventListener("click",function(){ if(cur>0)stepTo(cur-1)});
    var closeBtn=el("[data-close]"); if(closeBtn) closeBtn.addEventListener("click",close);
    var startBtn=el("#startDisc"); if(startBtn) startBtn.addEventListener("click",function(){ open(); stepTo(0)});
  }

  document.addEventListener("DOMContentLoaded",function(){
    wireDragDrop();
    // wire is defined; but DOMContentLoaded may fire before build fn
  });

  (function boot(){
    // build panels immediately
    buildPanels();
    wire();
    stepTo(0);
  })();
})();
'''

