"use strict";
(function () {
  var TYPES = ["d", "i", "s", "c"];
  var TYPE_NAME = {
    d: "Dominance · Доминирование",
    i: "Influence · Влияние",
    s: "Stability · Стабильность",
    c: "Compliance · Соответствие"
  };
  var STEP_LABELS = ["Войдите в первый", "Второй", "Третий",
    "Четвертый", "Пятый", "Шестой", "Седьмой", "Восьмой"];

  var $ = function (sel) { return document.querySelector(sel); };
  var $$ = function (sel) {
    return Array.prototype.slice.call(document.querySelectorAll(sel));
  };
  var elAll = function (sel, root) {
    return Array.prototype.slice.call((root || document).querySelectorAll(sel));
  };
  var esc = function (s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  };

  var cur = 0;
  var dragItem = null;
  var els = {};

  function buildPanels() {
    var html = "";
    for (var s = 0; s <= 7; s++) {
      html += '<div class="pane" data-step-pane="' + s + '"><div class="grid3">';
      for (var c = 0; c < 3; c++) {
        var qi = s * 3 + c;
        var items = QUESTIONS[qi];
        var cards = "";
        items.forEach(function (it, idx) {
          var isMajor = (idx === 0), isMinor = (idx === items.length - 1);
          var cls = "disc-item" + (isMajor ? " is-major" : "") + (isMinor ? " is-minor" : "");
          cards += '<li class="' + cls + '" draggable="true" data-item="' + idx + '" data-type="' + esc(it.type) + '"';
          if (isMajor) cards += ' data-major="1"';
          if (isMinor) cards += ' data-minor="1"';
          cards += '><span class="disc-item-text">' + esc(it.text) + "</span></li>";
        });
        html += '<div class="card"><div class="card__label">Я наиболее</div>'
          + '<ul class="disc-list" data-question="' + qi + '">' + cards + "</ul>"
          + '<div class="card__label">Я наименее</div></div>';
      }
      html += "</div></div>";
    }
    var root = $("#disc-root");
    if (root) root.innerHTML = html;
  }

  function build() {
    els.tabbar.innerHTML = "";
    STEP_LABELS.forEach(function (lab, i) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "tab" + (i === 0 ? " is-active" : "");
      b.setAttribute("data-step-btn", String(i));
      b.textContent = lab;
      els.tabbar.appendChild(b);
    });
    stepTo(0);
  }

  function stepTo(n) {
    cur = Math.min(7, Math.max(0, n));
    elAll("[data-step-btn]").forEach(function (t) {
      var i = Number(t.getAttribute("data-step-btn"));
      t.classList.toggle("is-active", i === cur);
    });
    elAll("[data-step-pane]").forEach(function (p) {
      var i = Number(p.getAttribute("data-step-pane"));
      p.classList.toggle("is-active", i === cur);
    });
    if (els.progressBar) els.progressBar.style.width = ((cur + 1) / 8 * 100) + "%";
    if (els.back) els.back.disabled = cur === 0;
    els.next.hidden = cur === 7;
    if (els.finish) els.finish.hidden = cur !== 7;
  }

  function openWizard() {
    var w = $("#wizardmodal");
    if (w) w.classList.add("is-open");
    document.body.classList.add("disc-no-scroll");
  }

  function closeWizard() {
    var w = $("#wizardmodal");
    if (w) w.classList.remove("is-open");
    document.body.classList.remove("disc-no-scroll");
  }

  function collectRows() {
    var rows = [];
    elAll("ul.disc-list").forEach(function (list) {
      elAll("li.disc-item", list).forEach(function (li) {
        rows.push({
          pos: Number(li.getAttribute("data-item")),
          type: li.getAttribute("data-type")
        });
      });
    });
    return rows;
  }

  function scoreRows(rows) {
    var maj = {};
    var min = {};
    TYPES.forEach(function (t) { maj[t] = 0; min[t] = 0; });
    rows.forEach(function (r) {
      if (r.pos === 0) maj[r.type]++;
      else if (r.pos === rows.length - 1) min[r.type]++;
    });
    var res = { d: 0, i: 0, s: 0, c: 0 };
    TYPES.forEach(function (t) { res[t] = maj[t] - min[t]; });
    return res;
  }

  function showResults() {
    var r = scoreRows(collectRows());
    var html = '<div class="result"><h2>Ваш DISC-профиль:</h2>';
    html += '<div class="scores-block">';
    TYPES.forEach(function (t) {
      var v = r[t] > 0 ? "+" + r[t] : String(r[t]);
      html += '<div class="score-card score-card-' + t + '">'
        + '<div class="score-type">' + t + '</div>'
        + '<div class="score-name">' + TYPE_NAME[t] + '</div>'
        + '<div class="score-value">' + v + '</div></div>';
    });
    html += '</div>';
    html += '<div class="legend">';
    html += '<div class="legend-item"><b>D:</b> Доминирование - решительность и напористость, стремление к результату.</div>';
    html += '<div class="legend-item"><b>I:</b> Влияние - общительность, энтузиаст, умение убеждать.</div>';
    html += '<div class="legend-item"><b>S:</b>Стабильность - стабильность, терпение, постоянство и надёжность.</div>';
    html += '<div class="legend-item"><b>C:</b> соответствие - соответствие стандартам, точность и аккуратность.</div>';
    html += '</div>';
    html += '<p class="disclaimer">Обратите внимание: мы не даем расшифровку вашего индивидуального результата. Инструмент для самопостигания и работы с командой.</p>';
    html += '<p class="disclaimer">Результаты не отправляются на сервер - всё вычисляется только у вас в браузере.</p>';
    var stage = $("#disc-root");
    if (stage) stage.innerHTML = html;
    document.body.classList.remove("disc-no-scroll");
    var w = $("#wizardmodal");
    if (w) w.classList.remove("is-open");
  }

  function wireDragAndDrop() {
    elAll("li.disc-item").forEach(function (li) {
      li.addEventListener("dragstart", function () {
        dragItem = li;
        setTimeout(function () { li.classList.add("is-dragging"); }, 0);
      });
      li.addEventListener("dragend", function () {
        li.classList.remove("is-dragging");
        dragItem = null;
      });
    });
    document.addEventListener("dragover", function (e) {
      if (!dragItem) return;
      var target = e.target && e.target.closest ? e.target.closest("li.disc-item") : null;
      if (!target || target === dragItem || !target.parentNode || target.parentNode === dragItem.parentNode) return;
      var wrap = dragItem.parentNode;
      if (!wrap) return;
      var rect = target.getBoundingClientRect();
      var after = e.clientY - rect.top < rect.height / 2;
      e.preventDefault();
      wrap.insertBefore(dragItem, after ? target : target.nextSibling);
    });
  }

  function wire() {
    var next = $("#step-next");
    if (next) next.addEventListener("click", function () {
      if (cur < 7) stepTo(cur + 1);
      else showResults();
    });
    var back = $("#step-back");
    if (back) back.addEventListener("click", function () {
      if (cur > 0) stepTo(cur - 1);
    });
    var closeBtn = $("#disc-close");
    if (closeBtn) closeBtn.addEventListener("click", closeWizard);
    var startBtn = $("#start-disc");
    if (startBtn) startBtn.addEventListener("click", function () { openWizard(); stepTo(0); });
    elAll("[data-close]").forEach(function (b) { b.addEventListener("click", closeWizard); });
  }

  function boot() {
    els.tabbar = $("#disc-tabs");
    els.progressBar = $("#disc-progress-bar");
    els.next = $("#step-next");
    els.back = $("#step-back");
    els.finish = $("#step-finish");
    buildPanels();
    build();
    wireDragAndDrop();
    wire();
    stepTo(0);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();
